dashboard.definition:
{
    "title": "Link Analysis Historical View",
    "description": "Load a graph previously saved with the Save State menu (app KV store cyto_graphs, or index=cyto via HTTP Event Collector).",
    "inputs": {
        "input_state": {
            "type": "input.dropdown",
            "title": "Previous State",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "cytoId"
            },
            "dataSources": {
                "primary": "ds_states"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        }
    },
    "dataSources": {
        "ds_states": {
            "type": "ds.search",
            "name": "Saved states",
            "options": {
                "query": "| inputlookup cyto_graphs\n| eval _time=saved_at\n| append [search index=cyto sourcetype=cyto:graph graph_id=* | fields _time graph_id description]\n| eval label=description.\" : \".strftime(_time, \"%c\").\" : \".graph_id, value=graph_id\n| sort 0 - _time\n| dedup value\n| table label value",
                "queryParameters": {
                    "earliest": "-365d@d",
                    "latest": "now"
                }
            }
        },
        "ds_state": {
            "type": "ds.search",
            "name": "Selected state",
            "options": {
                "query": "| inputlookup cyto_graphs where graph_id=$cytoId|s$\n| fields graph_info\n| append [search index=cyto sourcetype=cyto:graph graph_id=$cytoId|s$ | head 1 | fields _raw]\n| head 1\n| table graph_info _raw",
                "queryParameters": {
                    "earliest": "-365d@h",
                    "latest": "now"
                }
            }
        }
    },
    "visualizations": {
        "viz_state": {
            "type": "licoryx_link_analysis_app.link_analysis_studio",
            "title": "Load Former State",
            "dataSources": {
                "primary": "ds_state"
            }
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1440,
            "height": 960
        },
        "globalInputs": [
            "input_state"
        ],
        "structure": [
            {
                "item": "viz_state",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 1440,
                    "h": 800
                }
            }
        ]
    },
    "defaults": {}
}
